// Frozen pre-optimization forecast from d59dfb5; test oracle only.
const {add,mul}=require('../../shared/autonomous-economy.cjs');
const cmp=(a,b)=>a<b?-1:a>b?1:0;
const incoming=require('../../shared/economy-routes.cjs').incoming;
function opportunities(e){
  if(!e.trade?.routing)return [];if(e.trade.routing.planning)return e.trade.routing.planning.opportunities;
  const t=e.trade,r=t.routing,at=new Map(e.markets.flatMap(m=>m.provinceIds.map(id=>[id,m.id]))),markets=new Map(e.markets.map(m=>[m.id,m])),neighbors=new Map(e.markets.map(m=>[m.id,[]])),providers=new Map(),result=new Map();
  for(const edge of t.edges){neighbors.get(edge.a).push(edge.b);neighbors.get(edge.b).push(edge.a);}for(const list of neighbors.values())list.sort(cmp);
  const register=(province,good,capacity)=>{if(!capacity)return;if(!providers.has(good))providers.set(good,new Set());providers.get(good).add(at.get(province));};
  for(const f of e.enterprises){const recipe=e.recipes.find(v=>v.id===f.recipeId);register(f.provinceId,recipe.output.goodId,add(f.capacityBatches,f.inventories.find(s=>s.goodId===recipe.output.goodId).quantity));}
  for(const row of e.householdEconomy?.rows||[]){const h=e.households.find(h=>h.id===row.householdId);for(const stage of row.stages)register(h.provinceId,e.recipes.find(v=>v.id===stage.recipeId).output.goodId,stage.capacityBatches);for(const stock of row.inventories)register(h.provinceId,stock.goodId,stock.quantity);}
  for(const actor of [...e.households,...e.enterprises].sort((a,b)=>cmp(a.id,b.id))){const destination=at.get(actor.provinceId),m=markets.get(destination),distances=new Map([[destination,0]]),queue=[destination];for(let i=0;i<queue.length;i++){const id=queue[i],distance=distances.get(id);if(distance>=r.maxRouteEdges)continue;for(const other of neighbors.get(id))if(!distances.has(other)&&markets.get(other).accountingUnitId===m.accountingUnitId){distances.set(other,distance+1);queue.push(other);}}
    const demands=[];let budget=actor.cashMinor;
    if(actor.recipeId){const c=e.autonomy.firms.find(c=>c.enterpriseId===actor.id),recipe=e.recipes.find(r=>r.id===actor.recipeId);budget=Math.max(0,budget-mul(mul(c.plannedBatches,recipe.workersPerBatch),actor.wagePerWorkerMinor));if(c.status==='active')for(const input of recipe.inputs)demands.push({goodId:input.goodId,quantity:Math.max(0,mul(mul(c.plannedBatches,e.autonomy.rules.inputReserveMonths),input.quantity)-actor.inventories.find(s=>s.goodId===input.goodId).quantity-incoming(e,actor.id,input.goodId))});if(c.status!=='dormant'&&c.pendingCapacity){const good=e.autonomy.rules.capitalGoodId,reserve=require('../../shared/autonomous-economy.cjs').workingReserve(e,actor,recipe,m,c,false),plan=require('../../shared/autonomous-economy.cjs').capitalPlan(e,actor,c,m,Math.max(0,actor.cashMinor-reserve));demands.push({goodId:good,quantity:plan.quantity,reserve:add(reserve,plan.organization)});}}
    else{const row=e.householdEconomy?.rows.find(r=>r.householdId===actor.id),need=require('../../shared/agricultural-resources.cjs').foodNeed(e,actor),own=Math.min(require('../../shared/agricultural-resources.cjs').ruralNeed(e,actor,need),row?.inventories.find(s=>s.goodId===e.rules.foodGoodId).quantity||0),held=t.householdStocks.find(s=>s.householdId===actor.id).quantity;demands.push({goodId:e.rules.foodGoodId,quantity:Math.max(0,need-own-held-incoming(e,actor.id,e.rules.foodGoodId))});}
    for(const d of demands){const price=m.goods.find(g=>g.goodId===d.goodId).priceMinor,q=Math.min(d.quantity,Math.floor(Math.max(0,budget-(d.reserve||0))/price));if(!q)continue;budget-=mul(q,price);let best=null;for(const source of [...providers.get(d.goodId)||[]].sort(cmp)){if(source===destination||!distances.has(source))continue;const sourcePrice=markets.get(source).goods.find(g=>g.goodId===d.goodId).priceMinor,cost=add(mul(q,sourcePrice),mul(mul(Math.ceil(q/t.rules.unitsPerWorker),r.freightPerWorkerMinor),distances.get(source)));if(cost>=mul(q,price))continue;if(!best||cost<best.cost)best={source,cost};}if(best){const key=best.source+'|'+d.goodId;result.set(key,{marketId:best.source,goodId:d.goodId,quantity:add(result.get(key)?.quantity||0,q)});}}
  }
  return [...result.values()].sort((a,b)=>cmp(a.marketId,b.marketId)||cmp(a.goodId,b.goodId));
}
module.exports={opportunities};
